def djk(n, gp, st):
	dist = [P] * n
	pq = [(0, st)]
	dist[st] = 0
	while pq:
		(val, u) = heappop(pq)
		for (v, cost) in gp[u]:
			if dist[v] > dist[u] + cost:
				dist[v] = dist[u] + cost
				heappush(pq, (dist[v], v))
	return dist

def main():
